$('#selection-form').onsubmit=e=>{e.preventDefault();const q=questions.find(x=>x.id===activeSelectionId),selected=Number(new FormData(e.target).get('best-selection')),answer=q?.explanations.find(a=>a.id===selected);if(!q||q.author!==CURRENT_USER||lifecycleStatus(q)!=='open'||!answer)return;const wasSelected=Boolean(q.bestAnswer);q.bestAnswer={...answer};persistQuestions();renderQuestions();renderContributions();closeModals();toast(wasSelected?'Best explanation updated':'Best explanation selected',wasSelected?'The new selection is visible now. Its reward will be released at expiration.':'Your selected explanation is visible now. Its reward will be released when the question expires.')};
